wb = openpyxl.load_workbook('3_54590_answer_incorrect_index-match_4573_input.xlsx', data_only=False)
ws = wb['HR ']
# show all INDEX-MATCH formula variations normalized to check anomalies (e.g. INDEX array not #REF, MATCH lookup not A)
patterns={}
for row in ws.iter_rows():
    for cell in row:
        v=cell.value
        if isinstance(v,str) and 'INDEX' in v and 'MATCH' in v:
            # normalize row nums
            key=re.sub(r'\\\$A\d+', 'A#', re.sub(r\"'HR '!A\d+\", \"'HR '!A#\", v))
            patterns[key]=patterns.get(key,0)+1
for k,v in sorted(patterns.items()):
    print(v,k)
